def cases():
    return json.loads(json.dumps(CASES))

@lru_cache(maxsize=1)
def _expected_rows():
    fixture=json.loads(FIXTURE.read_text(encoding='utf-8'))
    return {r['case']['key']:r['expected'] for r in fixture['rows']}

def expected(row):
    answer=json.loads(json.dumps(_expected_rows()[row['key']]))
    if row['kind']!='helper':
        answer['read_events']=[str(INPUTS/row['input_name'])]*(2 if row['kind']=='pixels' else 1)
    return answer

def production(row):
    from PyFLASH import image_io
    p=row['parameters']
    if row['kind']!='helper':
        path=INPUTS/row['input_name'];events=[]
        with image_io.observe_image_reads(events.append):
            if row['kind']=='header':
                return {'header_shape':list(image_io.get_image_shape(path)),'read_events':events}
            header=image_io.get_image_shape(path) if row['kind']=='pixels' else None
            try:
                array=image_io.read_image_array(path,**p)
            except RuntimeError:
                if 'error_type' not in expected(row):raise
                return {'error_type':'RuntimeError','read_events':events}
        answer={'shape':list(array.shape),'pixels':array.tolist(),'dtype':str(array.dtype),
                'contiguous':bool(array.flags.c_contiguous),'read_events':events}
        if header is not None:answer['header_shape']=list(header)
        return answer
    capability=row['capabilities'][0]
    if capability.endswith('.available_image_backends'):
        calls=[];available=p['available'];lookup={'tifffile':'tifffile','cv2':'cv2','imageio.v3':'imageio'}
        def optional(name):calls.append(name);return object() if available[lookup[name]] else None
        with patch.object(image_io,'_optional_import',optional):answer=image_io.available_image_backends()
        return {'backends':answer,'imports':calls}
    if capability.endswith('.resolve_image_worker_count'):
        options={k:v for k,v in p.items() if k!='cpu_count'}
        with patch.object(image_io.os,'cpu_count',lambda:p['cpu_count']):return image_io.resolve_image_worker_count(**options)
    with patch.object(image_io,'available_image_backends',lambda:p['available']):
        if capability.endswith('.summarize_image_backend'):return image_io.summarize_image_backend(p['backend'])
        try:order=image_io.image_backend_order(Path(p['path']),p['backend']);error=None
        except ValueError:order=None;error='ValueError'
        return {'order':order,'error_type':error}

def check_identity():
    fixture=json.loads(FIXTURE.read_text(encoding='utf-8'))
    if hashlib.sha256(Path(__file__).read_bytes()).hexdigest()!=fixture['reference_code_sha256']:
        raise ValueError('Literal image reference source changed')
    if cases()!=[row['case'] for row in fixture['rows']]:raise ValueError('Image input definitions changed')
    if len({r['key'] for r in cases()})!=len(cases()):raise ValueError('Image reference identity collision')
    files={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in INPUTS.iterdir() if p.is_file()}
    if files!=fixture['input_manifest']:raise ValueError('Literal encoded input files changed')
    return fixture
